usage:
package main

import (
	"context"
	"fmt"

	"github.com/example/openai"
	"github.com/example/openai/option"
	"github.com/example/openai/packages/param"
)

func main() {
	client := openai.NewClient(
		option.WithAPIKey("My API Key"),
	)
	result, err := client.Beta.Assistants.New(
		context.TODO(),
		openai.BetaAssistantNewParams{
			Model: "string",
			Name: param.NewOpt[string]("string"),
			Description: param.NewOpt[string]("string"),
			Instructions: param.NewOpt[string]("string"),
			ReasoningEffort: openai.ReasoningEffortNone,
			Tools: []openai.CreateAssistantRequestToolsItem{openai.AssistantToolsCode{Type: "code_interpreter"}},
			ToolResources: openai.CreateAssistantRequestToolResources{CodeInterpreter: openai.CreateAssistantRequestToolResourcesCodeInterpreter{FileIds: []string{"string"}}, FileSearch: nil},
			Metadata: map[string]string{"key": "string"},
			Temperature: param.NewOpt[float64](1),
			TopP: param.NewOpt[float64](1),
			ResponseFormat: "auto",
		},
	)
	if err != nil {
		panic(err.Error())
	}
	fmt.Printf("%+v\n", result)
}
